ids_ = [r['order_id'] for r in rows]
return {"n":len(rows),"uniq":len(set(ids_)),"odd":odd,"t":{k:round(v,2) for k,v in sorted(t.items())},"statuses":sorted(set(str(r.get('status')) for r in rows))}

